"""``agentbrief`` command line: init, check, test, serve, hook."""

from __future__ import annotations

import argparse
import json
import re
import sys
from importlib import resources
from pathlib import Path
from typing import List, Optional

from . import __version__, core
from .models import BRIEF_DIR, features_dir, load_features

START, END = "<!-- agentbrief:start -->", "<!-- agentbrief:end -->"
HOOK_SCRIPT = ".claude/hooks/agentbrief-stop.sh"
HOOK_COMMAND = f'"$CLAUDE_PROJECT_DIR"/{HOOK_SCRIPT}'
HOOK_LAUNCHER = """#!/bin/sh
# Generated by `agentbrief init --claude-hook`. Claude Code runs this when the agent tries to stop;
# `agentbrief hook stop` exits 2 (send it back to work) while feature manifests are broken.
cd "$CLAUDE_PROJECT_DIR" 2>/dev/null || exit 0
for bin in .venv/bin/agentbrief venv/bin/agentbrief "$(command -v agentbrief)"; do
  [ -n "$bin" ] && [ -x "$bin" ] && exec "$bin" hook stop
done
exit 0  # agentbrief isn't installed here: never block the agent
"""


def find_root(start: Path) -> Path:
    """Nearest ancestor with a .agentbrief dir, else the git root, else ``start``."""
    for marker in (BRIEF_DIR, ".git"):
        for d in [start, *start.parents]:
            if (d / marker).exists():
                return d
    return start


def upsert_section(text: str, section: str) -> str:
    """Insert or replace the Agentbrief block in an AGENTS.md, leaving the rest untouched."""
    block = re.compile(re.escape(START) + r".*?" + re.escape(END), re.S)
    if block.search(text):
        return block.sub(lambda _: section.strip(), text)
    return (text.rstrip() + "\n\n" if text.strip() else "") + section.strip() + "\n"


def install_claude_hook(root: Path) -> bool:
    """Write the launcher and merge a Stop hook into .claude/settings.json. False if settings are unreadable."""
    settings_path = root / ".claude" / "settings.json"
    try:
        settings = json.loads(settings_path.read_text(encoding="utf-8")) if settings_path.exists() else {}
    except ValueError as exc:
        print(f"error: {settings_path.relative_to(root)} is not valid JSON ({exc}); not touching it")
        return False
    if not isinstance(settings, dict):
        print(f"error: {settings_path.relative_to(root)} is not a JSON object; not touching it")
        return False

    script = root / HOOK_SCRIPT
    script.parent.mkdir(parents=True, exist_ok=True)
    script.write_text(HOOK_LAUNCHER, encoding="utf-8")
    script.chmod(0o755)

    stop_groups = settings.setdefault("hooks", {}).setdefault("Stop", [])
    registered = any(h.get("command") == HOOK_COMMAND
                     for group in stop_groups for h in group.get("hooks", []))
    if not registered:
        stop_groups.append({"hooks": [{"type": "command", "command": HOOK_COMMAND}]})
        settings_path.write_text(json.dumps(settings, indent=2) + "\n", encoding="utf-8")
    print(f"{'kept' if registered else 'added'} Stop hook in .claude/settings.json -> {HOOK_SCRIPT}")
    return True


def cmd_init(root: Path, args: argparse.Namespace) -> int:
    features_dir(root).mkdir(parents=True, exist_ok=True)
    (root / BRIEF_DIR / ".gitignore").write_text(f"{core.CACHE_DIR}/\n", encoding="utf-8")
    section = resources.files("agentbrief").joinpath("templates/AGENTS_SECTION.md").read_text(encoding="utf-8")
    agents = root / "AGENTS.md"
    old = agents.read_text(encoding="utf-8") if agents.exists() else ""
    agents.write_text(upsert_section(old, section), encoding="utf-8")
    print(f"{'updated' if old else 'created'} {agents.relative_to(root)}")

    # Claude Code reads CLAUDE.md, not AGENTS.md; point it there.
    claude = root / "CLAUDE.md"
    if claude.exists():
        text = claude.read_text(encoding="utf-8")
        if "@AGENTS.md" not in text and "AGENTS.md" not in text:
            claude.write_text(text.rstrip() + "\n\n@AGENTS.md\n", encoding="utf-8")
            print("added @AGENTS.md import to CLAUDE.md")
    elif args.claude:
        claude.write_text("@AGENTS.md\n", encoding="utf-8")
        print("created CLAUDE.md importing AGENTS.md")
    if args.claude_hook and not install_claude_hook(root):
        return 1
    print(f"created {BRIEF_DIR}/features/. Agents will write manifests there.")
    print("next: ask your agent to document existing features, then run `agentbrief serve`")
    return 0


def check_errors(overview: dict) -> List[str]:
    errors = list(overview["manifest_errors"])
    for f in overview["features"]:
        errors += [f"{f['manifest']}: {p}" for p in f["problems"]]
    return errors


def cmd_check(root: Path, args: argparse.Namespace) -> int:
    overview = core.overview(root, args.base)
    errors = check_errors(overview)
    for e in errors:
        print(f"error: {e}")
    if overview["uncovered_files"]:
        print("warning: changed files not referenced by any feature manifest:")
        for p in overview["uncovered_files"]:
            print(f"  - {p}")
    n = len(overview["features"])
    print(f"{n} feature(s), {len(errors)} error(s)")
    return 1 if errors else 0


def cmd_test(root: Path, args: argparse.Namespace) -> int:
    features, errors = load_features(root)
    for e in errors:
        print(f"error: {e}")
    selected = [f for f in features if not args.ids or f.id in args.ids]
    unknown = set(args.ids) - {f.id for f in features}
    if unknown:
        print(f"unknown feature id(s): {', '.join(sorted(unknown))}")
        return 2
    nodeids = [t.nodeid for f in selected for t in f.tests]
    if not nodeids:
        print("no tests referenced by the selected features")
        return 1
    run = core.run_tests(root, sorted(set(nodeids)))
    status = 0
    for f in selected:
        outcomes = [core.aggregate(r["outcome"] for r in core.match_results(t.nodeid, run["results"]))
                    for t in f.tests]
        outcome = core.aggregate(outcomes) if outcomes else "no-tests"
        print(f"{outcome:>8}  {f.id}")
        if outcome not in ("passed", "skipped", "no-tests"):
            status = 1
            for t, o in zip(f.tests, outcomes):
                if o != "passed":
                    print(f"          {o}: {t.nodeid}")
    return status


def cmd_hook_stop(root: Path, args: argparse.Namespace) -> int:
    """Claude Code Stop hook: exit 2 with errors on stderr to make the agent fix its manifests."""
    try:
        event = json.loads(sys.stdin.read() or "{}")
    except ValueError:
        event = {}
    # Already continuing because of this hook: let it stop rather than loop forever.
    if isinstance(event, dict) and event.get("stop_hook_active"):
        return 0
    errors = check_errors(core.overview(root, None))
    if not errors:
        return 0
    lines = ["Feature manifests have errors. Fix them before finishing:"]
    lines += [f"  - {e}" for e in errors]
    lines.append("See the 'Feature manifests' section in AGENTS.md, then run `agentbrief check`.")
    print("\n".join(lines), file=sys.stderr)
    return 2


def cmd_serve(root: Path, args: argparse.Namespace) -> int:
    from .server import serve
    serve(root, host=args.host, port=args.port, base=args.base, open_browser=not args.no_browser)
    return 0


def main(argv: Optional[List[str]] = None) -> int:
    parser = argparse.ArgumentParser(prog="agentbrief", description="Review what coding agents built.")
    parser.add_argument("--version", action="version", version=__version__)
    parser.add_argument("--root", type=Path, help="project root (default: auto-detect)")
    sub = parser.add_subparsers(dest="cmd", required=True)

    p = sub.add_parser("init", help="set up .agentbrief/ and the AGENTS.md section")
    p.add_argument("--claude", action="store_true", help="also create CLAUDE.md importing AGENTS.md")
    p.add_argument("--claude-hook", action="store_true",
                   help="add a Claude Code Stop hook that won't let the agent finish with broken manifests")
    p.set_defaults(func=cmd_init)

    p = sub.add_parser("check", help="validate feature manifests (agents run this)")
    p.add_argument("--base", help="git ref to compare against for uncovered changes (default HEAD)")
    p.set_defaults(func=cmd_check)

    p = sub.add_parser("test", help="run the tests listed by features")
    p.add_argument("ids", nargs="*", help="feature ids (default: all)")
    p.set_defaults(func=cmd_test)

    p = sub.add_parser("hook", help="entry points for agent hooks (called by Claude Code, not by you)")
    p.add_argument("event", choices=["stop"])
    p.set_defaults(func=cmd_hook_stop)

    p = sub.add_parser("serve", help="open the review UI")
    p.add_argument("--port", type=int, default=8765)
    p.add_argument("--host", default="127.0.0.1")
    p.add_argument("--base", help="git ref to diff against, e.g. main (default HEAD)")
    p.add_argument("--no-browser", action="store_true")
    p.set_defaults(func=cmd_serve)

    args = parser.parse_args(argv)
    root = (args.root or find_root(Path.cwd())).resolve()
    return args.func(root, args)


if __name__ == "__main__":
    sys.exit(main())
